### 1. **Create a config/secrets module**

```javascript
// config/secrets.js - NOT committed to Git
module.exports = {
  // Database
  DB_HOST: process.env.DB_HOST,
  DB_PORT: process.env.DB_PORT || 5432,
  DB_USER: process.env.DB_USER,
  DB_PASSWORD: process.env.DB_PASSWORD, // Don't log this!
  DB_NAME: process.env.DB_NAME,

  // JWT Session
  JWT_SECRET: process.env.JWT_SECRET, // Required for production
  SESSION_SECRET: process.env.SESSION_SECRET, // Required for production

  // External Services
  API_KEY: process.env.API_KEY,
  GOOGLE_AUTH_ID: process.env.GOOGLE_AUTH_ID,

  // Must validate required fields at runtime
  validate() {
    const required = ['JWT_SECRET', 'DB_PASSWORD'];
    missing = required.filter(key => !this[key]);

    if (missing.length > 0) {
      console.error(`Missing required secrets: ${missing.join(', ')}`);
      process.exit(1);
    }
  }
};
