const apiLimiter = rateLimit({
    // 15 minutes window
    windowMs: 15 * 60 * 1000,
    // 100 requests per IP per window for API endpoint
    max: 100, 
    // Update the request counter continuously per sliding window
    standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
    // Only enable standard headers; disable legacy headers for brevity
    legacyHeaders: false,
    // Log information on each request
    handler: (req, res) => {
