            message: 'Too many requests from this IP, please try again later.',
            retryAfter: 15 * 60, // 15 minutes. Updates dynamically
        });
    },
    // Key generator: Use IP address, but add a custom identifier to differentiate
    // multiple requests from the same IP for different users
    keyGenerator: (req) => {
        return req.ip || req.connection.remoteAddress;
    },
    // Skip rate limiting for health checks or public bypass endpoints
    skip: (req) => {
        if (req.path === '/health') return true;
        if (req.path === '/api/public') return true;
        return false;
    }
