### 4. Local Development Fallback Pattern

Use both cloud manager and environment variables:

```javascript
async function loadSecrets() {
  const secrets = {};

  try {
    // Try AWS Secrets Manager first
    const awsSecrets = await getSecret('myapp-secrets');
    Object.assign(secrets, awsSecrets);
  } catch {
    // Fallback to .env for local development
    console.warn('Secrets Manager unavailable, using fallback');
    secrets.JWT_SECRET = process.env.JWT_SECRET || generateSecureRandomString();
    secrets.DB_PASSWORD = process.env.DB_PASSWORD || '';
  }

  return secrets;
}

function generateSecureRandomString(length = 64) {
  // Generate cryptographically strong random string
  return Array.from(crypto.getRandomValues(new Uint8Array(length / 2)))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('');
}
```

