### 5. Add Secret Validation Middleware

```javascript
// Validation function
function validateRequiredSecrets(app, requiredSecrets) {
  const missing = requiredSecrets.filter(r => !app.get(r));

  if (missing.length > 0) {
    throw new Error(`Missing required secrets from Secrets Manager: ${missing.join(', ')}`);
  }

  console.log(`✓ All ${requiredSecrets.length} required secrets loaded`);
}

// Usage
