**Recommendation:**
```javascript
app.use(express.json({ limit: '10kb' })); // Limit body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Validate content-type
const contentTypeValidator = (req, res, next) => {
  const allowedTypes = ['application/json', 'application/x-www-form-urlencoded'];

  if (req.is && !allowedTypes.includes(req.type('application/*'))) {
    return res.status(415).json({ error: 'Unsupported Media Type' });
  }
  next();
};

app.post('/api/endpoint', contentTypeValidator, (req, res) => {
  // ...
});
```

