async function getSecretsFromManager() {
  try {
    if (cachedSecrets) {
      consola.debug('Using cached secrets');
      return cachedSecrets;
    }

    const data = await secretsManager.getSecretValue({
      SecretId: process.env.SECRET_ARN || secretCacheKey
    }).promise();

    // The secret is stored as JSON string
    cachedSecrets = JSON.parse(data.SecretString);

    consola.info('Secrets loaded successfully from AWS Secrets Manager');
    return cachedSecrets;

  } catch (error) {
    // Fallback - if we're in development and secrets aren't in AWS, use environment variables
    if (process.env.NODE_ENV === 'development' || process.env.SKIP_SECRETS_MANAGER === 'true') {
      consola.warn('AWS Secrets Manager unavailable, falling back to environment variables');

      const secrets = {
        DATABASE_URL: process.env.DATABASE_URL,
        AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
        AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
        ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
        STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
        LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
        JWT_SECRET: process.env.JWT_SECRET
      };

      // Validate required secrets
      if (!secrets.JWT_SECRET) {
        secrets.JWT_SECRET = crypto.randomBytes(64).toString('hex');
        consola.warn('No JWT_SECRET found, generated temporary secret. Use .env file in development.');
      }

      return secrets;
    }

    consola.error('Failed to retrieve secrets from AWS Secrets Manager:', error.message);
    throw error;
  }
}

