### 3. Secure Secret Loading with Validation

```javascript
// secrets.js
const fs = require('fs');
const path = require('path');

class SecretManager {
  constructor() {
    // Ensure secrets are loaded once
    if (this.initialized) return;
    this.initialized = true;
  }

  loadEnvSecrets() {
    const requiredSecrets = [
      'JWT_SECRET',
      'DATABASE_URL',
      'REDIS_URL'
    ];

    const missing = requiredSecrets.filter(key => !process.env[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    if (process.env.NODE_ENV === 'development') {
      console.warn('⚠️  Running in development mode - some validations may be skipped');
    }
  }

  // Load secrets from separate file (never commit this file)
  loadExternalSecrets() {
    try {
      // Only in development
      if (process.env.NODE_ENV !== 'development') return;

      const secretFiles = fs.readdirSync('./secrets')
        .filter(file => file.endsWith('.env'));

      secretFiles.forEach(file => {
        const content = fs.readFileSync(
          path.join('./secrets', file),
          'utf-8'
        );

        // Parse and apply
        content.split('\n').forEach(line => {
          const [key, ...valueParts] = line.split('=');
          if (key && valueParts.length) {
            process.env[key.trim()] = valueParts.join('=').trim();
          }
        });
      });
    } catch (error) {
      // File doesn't exist - it's optional
      console.log('No external secrets file found');
    }
  }

  maskSecrets(envObject) {
    const masked = { ...envObject };
    const sensitiveKeys = [
      'password', 'secret', 'token', 'key', 'api_key', 'authorization'
    ];

    for (const [key, value] of Object.entries(envObject)) {
      if (sensitiveKeys.some(sk => key.toLowerCase().includes(sk))) {
        masked[key] = '***REDACTED***';
      }
    }

    return masked;
  }
}

const secretManager = new SecretManager();
module.exports = secretManager;
```

