### 7. Security Configuration Validator

```javascript
// config/validateEnv.js
const { body, validationResult, oneOf } = require('express-validator');
const { isUrl } = require('validator');

function validateEnvironment() {
  const errors = [];

  // PORT validation
  if (!process.env.PORT || isNaN(parseInt(process.env.PORT))) {
    errors.push('PORT must be a valid integer');
  }

  // SECURE NODE_ENV values
  const validEnvs = ['development', 'staging', 'production'];
  if (!validEnvs.includes(process.env.NODE_ENV)) {
    errors.push(`NODE_ENV must be one of: ${validEnvs.join(', ')}`);
  }

  // SECURE JWT_SECRET length validation
  if (process.env.JWT_SECRET && process.env.JWT_SECRET.length < 32) {
    errors.push('JWT_SECRET must be at least 32 characters');
  }

  // SECURE database URL validation
  if (process.env.DATABASE_URL && !isUrl(process.env.DATABASE_URL, {
    require_protocol: false
  })) {
    errors.push('DATABASE_URL must be a valid URL');
  }

  // Find if PII or secrets are being logged in env
  if (process.env.NODE_ENV === 'development') {
    const piiKeys = ['password', 'secret', 'token', 'ssn'];
    const foundPII = Object.keys(process.env)
      .filter(key =>
        piiKeys.some(pii => key.toLowerCase().includes(pii))
      );

    if (foundPII.length > 0) {
      console.warn(`⚠️  May have sensitive values in environment: ${foundPII.join(', ')}`);
    }
  }

  if (errors.length > 0) {
    console.error('❌ Environment validation failed:');
    errors.forEach(error => console.error(`  - ${error}`));
    process.exit(1);
  }
}

module.exports = validateEnvironment;
```

