  const needsGitignore = !gitignore.includes('.env');

  if (needsGitignore) {
    console.warn('⚠️  .gitignore missing .env patterns:');
    console.warn('  - .env');
    console.warn('  - .env.local');
  }

  const envFiles = fs.readdirSync('.').filter(file => file.startsWith('.env'));
  if (envFiles.length > 0) {
    envFiles.forEach(file => {
      if (!gitignore.includes(file)) {
        console.warn(`⚠️  {file} may be tracked by git`);
        console.warn('  → Add to .gitignore to prevent secret leaks\n');
      } else {
        console.log(`✓ {file} is protected in .gitignore`);
      }
    });
  } else {
    console.log('ℹ️  No .env files found (acceptable)');
  }

  // Check for environment variable usage patterns
  const { execSync } = require('child_process');
  try {
    const secretEnvVars = [
      'JWT_SECRET',
      'PASSWORD',
      'SECRET',
      'API_KEY',
      'AUTH_TOKEN',
      'SSN',
      'CREDIT_CARD'
    ];

    console.log('\n🔐 Checking for sensitive environment variable patterns...\n');

    const envFilesChecked = fs.readdirSync('.').filter(file => file.startsWith('.env'));
    let secretsFound = false;

    envFilesChecked.forEach(file => {
      const content = fs.readFileSync(file, 'utf-8');
      secretEnvVars.forEach(secret => {
        if (content.includes(secret)) {
          console.warn(`⚠️  Found potential secret key '{secret}' in ${file}`);
          secretsFound = true;
        }
      });
    });

    if (!secretsFound) {
      console.log('✓ No obvious secrets found in .env files');
    }
  } catch (error) {
    console.log('⚠️  Could not check environment files');
  }

  // Check .gitignore exists
  if (!fs.existsSync('.gitignore')) {
    console.warn('⚠️  No .gitignore file found');
    console.warn('  → Secrets may be committed by default');
  }
}

checkEnvFiles();
