// secrets-validation.js - Validate secret strength at startup
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

function validateSecrets() {
  const envPath = path.join(__dirname, '.env');
  let envContent = '';

  try {
    envContent = fs.readFileSync(envPath, 'utf8');

    // Check for secrets that require minimum length
    const secretsToValidate = [
      { key: 'JWT_SECRET', minLength: 32 },
      { key: 'API_KEY', minLength: 24 },
      { key: 'ENCRYPTION_KEY', minLength: 32 }
    ];

    secretsToValidate.forEach(({ key, minLength }) => {
      const value = process.env[key];

      if (!value) {
        console.warn(`⚠️  Warning: ${key} is not set`);
        return;
      }

      if (value.length < minLength) {
        throw new Error(`Security Risk: ${key} is too short (minimum ${minLength} characters)`);
      }

      // Check for weak patterns
      if (/^(password|secret|key|token)$/i.test(key) && value.length < 8) {
        throw new Error(`Security Risk: ${key} credential is too weak`);
      }

      console.log(`✅ ${key} is properly configured`);
    });

    // Validate environment is set correctly
    if (process.env.NODE_ENV === 'production') {
      if (!process.env.JWT_SECRET || process.env.JWT_SECRET.length < 32) {
        throw new Error('JWT_SECRET must be set to a strong secret in production');
      }
    }

  } catch (error) {
    console.error(`❌ Secret validation failed: ${error.message}`);
    process.exit(1);
  }
}

module.exports = validateSecrets;
```

