# Security Review Report for app.js

## Summary
This document provides a comprehensive security review of `app.js` covering common vulnerabilities and OWASP Top 10 concerns.

---

## Findings

### 🔴 HIGH SEVERITY

#### 1. OWASP Top 10: A01:2021 - Broken Access Control

**Issue:** No authentication or authorization is implemented.

All endpoints are publicly accessible without any authentication:

```javascript
// VULNERABLE: Anyone can access this endpoint
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Impact:** Unauthorized users can view all user data, including potentially sensitive information like emails.

**Recommendation:** Implement authentication middleware and role-based access control:

```javascript
// SOLUTION: Add authentication middleware
const jwt = require('jsonwebtoken');
const crypto = require('crypto');

// Secure your password hashing
const bcrypt = require('bcryptjs');

// Middleware to verify JWT tokens
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Middleware for role-based access control
function requireRole(role) {
  return (req, res, next) => {
    if (req.user && req.user.role === role) {
      next();
    } else {
      res.status(403).json({ error: 'Insufficient permissions' });
    }
  };
}

// Apply authentication to sensitive endpoints
app.get('/users/me', authenticateToken, (req, res) => {
  res.json({
    id: req.user.id,
    name: 'Alice',
    email: 'alice@example.com'
  });
});

app.get('/users', authenticateToken, requireRole('admin'), (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

#### 2. Missing Input Validation / A02:2021 - Cryptographic Failures (Related)

**Issue:** No input validation on query parameters or request data endpoints.

**Vulnerability Demonstration:**
```bash
# Anyone can trigger crash or unexpected behavior
curl "http://localhost:3000/users?limit=99999999999999999999999999999"

# Potential for resource exhaustion
curl -G "http://localhost:3000/users" --data-urlencode "id[1]=malicious"
```

**Recommendation:** Add input validation and sanitization:

```javascript
// SOLUTION: Add input validation with Joi or express-validator
const Joi = require('joi');

// Schema for user requests
const userIdSchema = Joi.object({
  id: Joi.number().integer().min(1).max(1000).required()
});

// Apply validation middleware
function validateRequest(schema) {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.query);
    if (error) {
      return res.status(400).json({
        error: 'Invalid request parameters',
        details: error.details.map(d => d.message)
      });
    }
    req.query = value; // Replace with validated values
    next();
  };
}

// Use in route
app.get('/users', validateRequest(userIdSchema), (req, res) => {
  // Safe to use validated req.query.id
});

// Or using express-validator
const { body, query, validationResult } = require('express-validator');

app.get('/users', query('limit')
  .optional()
  .isInt({ min: 1, max: 100 })
  .withMessage('Limit must be between 1 and 100'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to proceed
    res.json([...users]);
  });
```

---

### 🟡 MEDIUM SEVERITY

#### 3. No HTTPS Enforcement

**Issue:** Server runs over HTTP without requiring HTTPS.

**Impact:** Man-in-the-middle attackers can intercept and modify requests between client and server.

**Recommendation:** Force HTTPS and handle HTTP to HTTPS redirect:

```javascript
// SOLUTION: Use environment variable for protocol
const PORT = process.env.PORT || 443;
const IS_SECURE = process.env.NODE_ENV === 'production';

const app = express();

// Force HTTPS in production
if (IS_SECURE) {
  app.use((req, res, next) => {
    if (!req.secure && req.get('x-forwarded-proto') !== 'https') {
      return res.redirect(301, `https://${req.get('host')}${req.originalUrl}`);
    }
    next();
  });
}

// Use HTTPS with allowInsecureHttpRequests for development
const httpsOptions = {
  key: fs.readFileSync('path/to/private.key'),
  cert: fs.readFileSync('path/to/certificate.crt'),
};

if (IS_SECURE) {
  app.listen(PORT, () => {
    console.log(`Server running on HTTPS port ${PORT}`);
  });
} else {
  app.listen(PORT, () => {
    console.log('⚠️  WARNING: Running in insecure HTTP mode (development only)');
  });
}
```

---

#### 4. Information Leakage - Development Mode

**Issue:** Server may leak stack traces or detailed error messages in development mode.

**Impact:** Attackers gain information about dependencies, versions, and application structure.

**Recommendation:** Configure proper error handling:

```javascript
// SOLUTION: Configure Express for production environment
const env = process.env.NODE_ENV || 'development';

app.use((err, req, res, next) => {
  if (env === 'production') {
    // Generic error message in production
    console.error(err.stack);
    res.status(500).json({ error: 'Internal server error' });
  } else {
    // Detailed error in development
    res.status(500).json({
      error: err.message,
      stack: err.stack,
    });
  }
});

// Learning: This code is missing - you need to add error handling middleware
```

---

#### 5. Insufficient Server Headers

**Issue:** Missing security headers (CSP, X-Content-Type-Options, etc.)

**Recommendation:** Set security headers:

```javascript
// SOLUTION: Add security headers middleware
const helmet = require('helmet');

// Use helmet for predefined security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"]
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  xssFilter: true,
  noSniff: true,
  ieNoOpen: true,
}));

// Additional custom headers
app.use((req, res, next) => {
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('X-Permitted-Cross-Domain-Policies', 'none');
  next();
});
```

---

### 🟢 LOW SEVERITY

#### 6. Hardcoded Secrets / Environment Questions

**Issue:** No secrets management implementation.

**Recommendation:** Use environment variables:

```javascript
// SOLUTION: Use environment variables for sensitive data
const port = process.env.PORT || 3000;
const secret = process.env.JWT_SECRET || '';
const databaseUrl = process.env.DATABASE_URL;

if (!process.env.JWT_SECRET) {
  console.error('WARNING: JWT_SECRET is not set');
}

// Source: .env.test shows test app defaults; REDUNDANT
// REDUNDANT - these should not be read from test env file at runtime
```

Source: .env.test are only needed for test harness or loading test config. Using them at runtime is risky; add runtime checks and defaults only.

---

#### 7. Missing Rate Limiting

**Issue:** No protection against brute force attacks or DoS.

**Recommendation:** Add rate limiting:

```javascript
// SOLUTION: Add rate limiting
const rateLimit = require('express-rate-limit');

// General rate limiter
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Strict limiter for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Limit each IP to 5 requests
  message: 'Too many authentication attempts',
});

// Apply rate limiting
app.use('/api/', generalLimiter);

// More strict for authentication endpoints
app.post('/login', authLimiter, (req, res) => {
  // Authentication logic
});
```

---

#### 8. No CORS Policy

**Issue:** CORS is not configured, allowing requests from any origin.

**Recommendation:** Restrict CORS appropriately:

```javascript
// SOLUTION: Configure CORS
const cors = require('cors');

// Only allow specific origins in production
const corsOptions = {
  origin: process.env.NODE_ENV === 'production'
    ? ['https://yourdomain.com']
    : process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
};

app.use(cors(corsOptions));

// Or allow all origins (not recommended):
// app.use(cors());
```

