## Findings

### 🔴 HIGH SEVERITY

#### 1. OWASP Top 10: A01:2021 - Broken Access Control

**Issue:** No authentication or authorization is implemented.

All endpoints are publicly accessible without any authentication:

```javascript
// VULNERABLE: Anyone can access this endpoint
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Impact:** Unauthorized users can view all user data, including potentially sensitive information like emails.

**Recommendation:** Implement authentication middleware and role-based access control:

```javascript
// SOLUTION: Add authentication middleware
const jwt = require('jsonwebtoken');
const crypto = require('crypto');

// Secure your password hashing
const bcrypt = require('bcryptjs');

// Middleware to verify JWT tokens
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Middleware for role-based access control
function requireRole(role) {
  return (req, res, next) => {
    if (req.user && req.user.role === role) {
      next();
    } else {
      res.status(403).json({ error: 'Insufficient permissions' });
    }
  };
}

// Apply authentication to sensitive endpoints
app.get('/users/me', authenticateToken, (req, res) => {
  res.json({
    id: req.user.id,
    name: 'Alice',
    email: 'alice@example.com'
  });
});

app.get('/users', authenticateToken, requireRole('admin'), (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

